const entry = JSON.stringify({ id: record.id, kind: record.kind, status: record.status || "observation", at: record.at,
  title: record.title, paths: record.paths, source, sourceExcerpt, retrievalReason: record.retrievalReason,
  text: record.match ? `${record.match.context}\n${record.match.text}` : excerptFor(record.text, words, record.kind === "lesson" ? 2400 : 1400),
  section: record.match && store.get(record.match.recordId).text.length > 1200 ? { id: record.match.id, recordId: record.match.recordId, start: record.match.start, end: record.match.end, headings: record.match.headings, metadata: sectionMetadata(store.get(record.match.recordId), record.match.text, record.match.context), file: store.file(store.get(record.match.recordId)) } : undefined,
  excerpt: record.text.length > (record.kind === "lesson" ? 2400 : 1400),
  file: store.file(record), evidence: record.evidence,
  aliases: cached.aliases.get(record.id)?.slice(0, 8) });
if (text.length + entry.length + 1 > maxChars) {
  diagnostics.candidate(record.id, { disposition: "context-budget", entryChars: entry.length + 1, remainingChars: Math.max(0, maxChars - text.length) });
  continue;
}
text += entry + "\n";
selected.push(record.id); seen.add(key);
